import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group } from 'three/webgpu';
import { uv, mix, smoothstep, color as tslColor, vec3, Fn } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, PlaneGeometry, Mesh, Color } = THREE;

  const group = new Group();
  group.name = 'pricing-card-1-label';

  const spec = config.intent?.visualSpec ?? {};
  const colors = spec.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };
  const items = config.textContent ?? spec.textContent ?? [];

  // --- Engineered gradient backdrop card (surface -> ink, vertical) ---
  const cardMat = new MeshBasicNodeMaterial();
  const cTop = tslColor(colors.surface);
  const cBot = tslColor(colors.ink);
  cardMat.colorNode = mix(cBot, cTop, smoothstep(0.0, 1.0, uv().y));
  cardMat.transparent = false;

  const cardGeo = new PlaneGeometry(1.5, 0.95, 1, 1);
  const card = new Mesh(cardGeo, cardMat);
  card.position.set(0, 0, -0.03);
  card.renderOrder = 0;
  group.add(card);

  // --- Decorative orb image plane (atlas region 0,0,512,320 -> aspect 1.6) ---
  const imgMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0.92 });
  const imgGeo = new PlaneGeometry(1.5, 0.95);
  const img = new Mesh(imgGeo, imgMat);
  img.position.set(0, 0, 0);
  img.renderOrder = 1;
  group.add(img);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.minFilter = THREE.LinearFilter;
      tex.magFilter = THREE.LinearFilter;
      imgMat.map = tex;
      imgMat.needsUpdate = true;
    });
  }

  // --- Accent signal-red edge bar (the ONE brightest element, <=10% frame) ---
  const accentMat = new MeshBasicNodeMaterial();
  accentMat.colorNode = tslColor(colors.accent);
  const accentGeo = new PlaneGeometry(1.5, 0.045);
  const accent = new Mesh(accentGeo, accentMat);
  accent.position.set(0, 0.95 * 0.5 - 0.0225, 0.005);
  accent.renderOrder = 2;
  group.add(accent);

  // --- Text: "Pricing 1" headline, paper on dark, centered ---
  for (const item of items) {
    const fontSize = item.typography?.fontSize ?? 39;
    const role = item.role ?? 'headline';
    const isCaption = role === 'caption' || role === 'body';
    const txt = ctx.fontAtlas.createText(String(item.text), {
      fontSize,
      color: colors.paper,
      align: 'center',
      letterSpacingPx: isCaption ? 4 : 0,
    });
    txt.position.set(0, -0.06, 0.02);
    txt.renderOrder = 3;
    group.add(txt);
  }

  // --- Entrance: rise-in + weighted-settle, power3.out, no linear easing ---
  const tl = gsap.timeline();
  group.position.y = 0.4;
  group.scale.set(1, 1, 1);
  tl.to(group.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out',
  });
  tl.to(group.scale, {
    x: 1.04,
    y: 1.04,
    duration: 0.5,
    ease: 'power2.out',
  }, 0.5);
  tl.to(group.scale, {
    x: 1.0,
    y: 1.0,
    duration: 0.9,
    ease: 'power4.out',
  }, 1.0);

  // --- Handlers (none per spec) ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    tl.kill();
    cardGeo.dispose();
    cardMat.dispose();
    imgGeo.dispose();
    imgMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
  };

  return group;
}
